<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit,Signatories,GeneratedDocuments,Pdf,Accounts,Authorization};
final class Official {
 public static function template(\PDO $p,int $u,int $programme,string $kind,string $type,string $title,string $body):int {ExtendedMigrations::require($p);$r=Policy::programme($p,$programme);Policy::require($p,$u,'outputs.manage',$r);if(!in_array($kind,['LETTER','CERTIFICATE'],true)||!preg_match('/\A[a-z0-9_]{1,64}\z/',$type))throw new \RuntimeException('Template tidak sah.');Database::query($p,'INSERT INTO training_templates(programme_id,kind,type_key,title,body,created_by) VALUES(?,?,?,?,?,?)',[$programme,$kind,$type,Core::text($title),Core::text($body,10000),$u]);$id=(int)$p->lastInsertId();Audit::record($p,'output.template_created',$u,(int)$r['owner_organisation_id'],(string)$id,'training');return $id;}
 public static function draft(\PDO $p,int $u,int $programme,int $template,?int $registration,string $role,string $reference,array $signatories,?int $replaces=null):int {return Core::tx($p,function()use($p,$u,$programme,$template,$registration,$role,$reference,$signatories,$replaces){$r=Policy::published($p,$programme,true);Policy::require($p,$u,'outputs.manage',$r);$t=Database::query($p,'SELECT * FROM training_templates WHERE id=? AND programme_id=?',[$template,$programme])->fetch();if(!$t)throw new \RuntimeException('Template di luar program.');if(count($signatories)<1||count($signatories)>2)throw new \RuntimeException('1–2 signatories diperlukan.');$ss=[];foreach(array_unique($signatories) as $id)$ss[]=Signatories::snapshot($p,$u,Core::id($id),(int)$r['owner_organisation_id']);$recipient=null;if($registration){$reg=Workflow::registration($p,$u,$programme,$registration,'outputs.manage',$t['kind']==='CERTIFICATE');if(!Database::query($p,'SELECT 1 FROM training_participation_assignments a JOIN training_participation_roles pr ON pr.id=a.role_id WHERE a.registration_id=? AND pr.programme_id=? AND pr.code=? AND pr.is_active=1',[$registration,$programme,$role])->fetchColumn())throw new \RuntimeException('Role penerima tidak sepadan.');$recipient=json_decode($reg['snapshot_json'],true);}elseif($t['kind']==='CERTIFICATE')throw new \RuntimeException('Certificate memerlukan penerima.');if($t['kind']==='CERTIFICATE'&&(!Attendance::complete($p,$u,$programme,$registration)||!Evaluation::eligible($p,$programme,$registration)))throw new \RuntimeException('Syarat attendance/evaluation belum lengkap.');$attachment=[];if($t['kind']==='LETTER')foreach(Database::query($p,"SELECT tr.* FROM training_registrations tr WHERE programme_id=? AND status IN ('PENDING','CONFIRMED') ORDER BY id",[$programme])->fetchAll() as $item){$s=json_decode($item['snapshot_json'],true);$s['roles']=Database::query($p,'SELECT pr.name FROM training_participation_assignments a JOIN training_participation_roles pr ON pr.id=a.role_id WHERE a.registration_id=?',[$item['id']])->fetchAll(\PDO::FETCH_COLUMN);$attachment[]=$s;}
 if($replaces){$old=Database::query($p,"SELECT * FROM training_outputs WHERE id=? AND programme_id=? AND kind=? AND status='VOID'",[$replaces,$programme,$t['kind']])->fetch();if(!$old||$old['registration_id']!=$registration)throw new \RuntimeException('Reissue memerlukan original VOID recipient sama.');}
 $pc=Policy::config($p,$r,true);$contact=$pc['coordinator_id']?Database::query($p,'SELECT sp.full_name,sp.official_email,sp.phone FROM users u JOIN staff_profiles sp ON sp.staff_identity_id=u.staff_identity_id WHERE u.id=? AND u.is_active=1',[$pc['coordinator_id']])->fetch():null;if($t['kind']==='LETTER'&&(!$contact||!$contact['official_email']))throw new \RuntimeException('Penyelaras/contact rasmi diperlukan untuk surat.');$snapshot=['contact'=>$contact,'programme'=>$pc,'programme_revision'=>$r['published_revision_id'],'recipient'=>$recipient,'role'=>$role,'template'=>$t,'signatories'=>$ss,'attachment'=>$attachment,'date'=>gmdate('Y-m-d'),'finalisation_started_at'=>gmdate('c')];Database::query($p,'INSERT INTO training_outputs(programme_id,registration_id,kind,role_key,template_id,reference_number,snapshot_json,verification_key,created_by,replaces_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$programme,$registration,$t['kind'],Core::text($role,64),$template,Core::text($reference),Workflow::json($snapshot),bin2hex(random_bytes(16)),$u,$replaces]);$id=(int)$p->lastInsertId();Audit::record($p,'output.draft_created',$u,(int)$r['owner_organisation_id'],(string)$id,'training',null,null,['kind'=>$t['kind'],'replaces'=>$replaces]);return $id;});}
 public static function transition(\PDO $p,int $u,int $id,string $action,string $reason):void {Core::tx($p,function()use($p,$u,$id,$action,$reason){$o=Database::query($p,'SELECT * FROM training_outputs WHERE id=? FOR UPDATE',[$id])->fetch();if(!$o)throw new \RuntimeException('Output tidak wujud.');$r=Policy::programme($p,(int)$o['programme_id'],true);$old=$o['status'];$reason=Core::text($reason,500);if($action==='VOID'){Policy::require($p,$u,'outputs.approve',$r);if($old!=='LOCKED')throw new \RuntimeException('VOID hanya locked output.');$to='VOID';Database::query($p,'UPDATE training_outputs SET void_reason=? WHERE id=?',[$reason,$id]);}else{Policy::require($p,$u,$action==='APPROVE'?'outputs.approve':'outputs.manage',$r);$trans=$o['kind']==='LETTER'?['REVIEW'=>['DRAFT','REVIEW'],'APPROVE'=>['REVIEW','APPROVED'],'PUBLISH'=>['APPROVED','PUBLISHED'],'LOCK'=>['PUBLISHED','LOCKED']]:['PREVIEW'=>['DRAFT','PREVIEW'],'APPROVE'=>['PREVIEW','APPROVED'],'GENERATE'=>['APPROVED','GENERATED'],'LOCK'=>['GENERATED','LOCKED']];if(!isset($trans[$action])||$old!==$trans[$action][0])throw new \RuntimeException('Transition tidak sah.');$to=$trans[$action][1];if($action==='APPROVE'){Workflow::reviewer($p,$u,(int)$o['created_by']);Database::query($p,'UPDATE training_outputs SET approved_by=? WHERE id=?',[$u,$id]);}if($to==='LOCKED'){$s=json_decode($o['snapshot_json'],true);if($o['kind']==='CERTIFICATE'){Workflow::registration($p,$u,(int)$r['id'],(int)$o['registration_id'],'outputs.manage');if(!Attendance::complete($p,$u,(int)$r['id'],(int)$o['registration_id'])||!Evaluation::eligible($p,(int)$r['id'],(int)$o['registration_id']))throw new \RuntimeException('Certificate eligibility berubah.');}$pdf=self::render($p,$u,$o,$s);$doc=GeneratedDocuments::store($p,$u,(int)$r['id'],$s['template']['title'],$pdf);Database::query($p,'UPDATE training_outputs SET document_id=?,file_checksum=?,locked_at=UTC_TIMESTAMP() WHERE id=?',[$doc,hash('sha256',$pdf),$id]);if($o['registration_id']){$uid=Database::query($p,'SELECT u.id FROM users u JOIN training_registrations r ON r.staff_identity_id=u.staff_identity_id WHERE r.id=? AND u.is_active=1',[$o['registration_id']])->fetchColumn();if($uid)Events::emit($p,(int)$r['id'],(int)$uid,'output:'.$id,'Dokumen '.$o['kind'].' untuk role '.$o['role_key'].': '.$o['reference_number'].' tersedia dalam My Documents.');}}}
 Database::query($p,'UPDATE training_outputs SET status=? WHERE id=?',[$to,$id]);Database::query($p,'INSERT INTO training_output_history(output_id,actor_id,previous_status,new_status,reason) VALUES(?,?,?,?,?)',[$id,$u,$old,$to,$reason]);Audit::record($p,'output.transition',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$reason,['status'=>$old],['status'=>$to]);});}
 private static function render(\PDO $p,int $u,array $o,array $s):string {$c=$s['programme'];$recipient=$s['recipient'];$replace=['{{name}}'=>$recipient['full_name']??'Senarai peserta','{{programme}}'=>$c['title'],'{{role}}'=>$s['role'],'{{date}}'=>$s['date'],'{{start}}'=>$c['start_at'],'{{end}}'=>$c['end_at'],'{{venue}}'=>$c['venue'],'{{organiser}}'=>$c['organiser'],'{{reference}}'=>$o['reference_number']];$lines=[$s['template']['title'],'No. rujukan: '.$o['reference_number'],'Tarikh: '.$s['date'],'',strtr($s['template']['body'],$replace),'', 'Program: '.$c['title'],'Masa UTC: '.$c['start_at'].' — '.$c['end_at'],'Tempat: '.$c['venue'],'Online: '.$c['online_url'],'Penganjur: '.$c['organiser'],'Tujuan: '.$c['objectives'],'Pegawai dihubungi: '.($s['contact']['full_name']??'').' '.($s['contact']['official_email']??'').' '.($s['contact']['phone']??''),''];if($recipient)$lines[]='Penerima: '.$recipient['full_name'].' | Role: '.$s['role'];if($s['attachment']){$lines[]='Lampiran — Snapshot peserta';foreach($s['attachment'] as $i=>$staff)$lines[]=($i+1).'. '.$staff['full_name'].' | '.($staff['position_name']??'').' | '.$staff['organisation_name'].' | Unit ID '.($staff['unit_id']??'').' | '.implode(', ',$staff['roles']);}$sig=[];foreach($s['signatories'] as $sign){$v=Database::query($p,'SELECT * FROM document_versions WHERE document_id=? AND version=?',[$sign['document_id'],$sign['version']])->fetch();if(!$v||!hash_equals($sign['checksum'],$v['checksum'])||!preg_match('/\A[a-f0-9]{64}\z/',$v['storage_key']))throw new \RuntimeException('Signature snapshot tidak sah.');$path=APP_ROOT.'/storage/documents/'.$v['storage_key'];$bytes=file_get_contents($path);if(!hash_equals($sign['checksum'],hash('sha256',$bytes)))throw new \RuntimeException('Signature asset integrity gagal.');$sig[]=['bytes'=>$bytes,'name'=>$sign['name'],'position'=>$sign['position']];}$qr=$o['kind']==='CERTIFICATE'?Qr::matrix(Accounts::origin().'/training/verify?key='.$o['verification_key']):null;return Pdf::generate($lines,$sig,$qr);}
 public static function preview(\PDO $p,int $u,int $id):string {$o=Database::query($p,'SELECT * FROM training_outputs WHERE id=?',[$id])->fetch();if(!$o)throw new \RuntimeException('Output tidak wujud.');Policy::require($p,$u,'outputs.manage',Policy::programme($p,(int)$o['programme_id']));return self::render($p,$u,$o,json_decode($o['snapshot_json'],true));}
 public static function verify(\PDO $p,string $key):array {ExtendedMigrations::require($p);if(!preg_match('/\A[a-f0-9]{32}\z/',$key))throw new \RuntimeException('Verification key tidak sah.');$o=Database::query($p,"SELECT * FROM training_outputs WHERE verification_key=? AND kind='CERTIFICATE' AND status IN ('LOCKED','VOID')",[$key])->fetch();if(!$o)throw new \RuntimeException('Certificate tidak ditemui.');$s=json_decode($o['snapshot_json'],true);return ['recipient'=>$s['recipient']['full_name'],'programme'=>$s['programme']['title'],'date'=>$s['date'],'role'=>$s['role'],'status'=>$o['status']==='VOID'?'VOID':'VALID','certificate_id'=>$o['id']];}
 public static function accessDocument(\PDO $p,int $u,array $d,bool $manage):bool {if(!ExtendedMigrations::ready($p))return false;$signature=Database::query($p,'SELECT organisation_id FROM core_signatories WHERE signature_document_id=?',[$d['id']])->fetchColumn();if($signature){if(!Authorization::super($p,$u))Authorization::require($p,$u,'training.signatories.manage',(int)$signature);return true;}$o=Database::query($p,'SELECT * FROM training_outputs WHERE document_id=?',[$d['id']])->fetch();if(!$o)return false;$r=Policy::programme($p,(int)$o['programme_id']);if(Policy::allowed($p,$u,'outputs.manage',$r))return true;if($manage||$o['status']!=='LOCKED'||!$o['registration_id'])throw new \RuntimeException('Official document access denied.');$a=Policy::actor($p,$u);if(!Database::query($p,'SELECT 1 FROM training_registrations WHERE id=? AND staff_identity_id=?',[$o['registration_id'],$a['staff_identity_id']])->fetchColumn())throw new \RuntimeException('Dokumen bukan penerima ini.');return true;}
 public static function acknowledge(\PDO $p,int $u,int $programme,int $rid,bool $attend,string $reason):void {Core::tx($p,function()use($p,$u,$programme,$rid,$attend,$reason){$reg=Workflow::registration($p,$u,$programme,$rid);$a=Policy::actor($p,$u);if((int)$reg['staff_identity_id']!==(int)$a['staff_identity_id'])throw new \RuntimeException('Peserta sahaja.');$r=Policy::programme($p,$programme,true);$reason=Core::text($reason,500);Database::query($p,'INSERT INTO training_acknowledgements(registration_id,status,reason,actor_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),reason=VALUES(reason),actor_id=VALUES(actor_id)',[$rid,$attend?'CONFIRMED':'DECLINED',$reason,$u]);if(!$attend)Registration::decide($p,$u,$programme,$rid,'WITHDRAW',$reason);Audit::record($p,'registration.acknowledged',$u,(int)$r['owner_organisation_id'],(string)$rid,'training',$reason,null,['attend'=>$attend]);});}
}
